/* 🙂 */ outputLine("before");
pick := inputInt();
if pick == 0 { outputLine(textAt("🙂x", -1)); }
else if pick == 1 { outputLine(textAt("🙂x", 2)); }
else if pick == 2 { outputLine(textAt("", 0)); }
else if pick == 3 { outputLine(textSlice("🙂ab", -1, 1)); }
else if pick == 4 { outputLine(textSlice("🙂ab", 2, 1)); }
else if pick == 5 { outputLine(textSlice("🙂ab", 0, 4)); }
else if pick == 6 { values: List<Int> = [7]; outputLine(values[-1]); }
else if pick == 7 { values: List<Int> = [7]; outputLine(values[/* سلام */ 1]); }
else if pick == 8 { values: List<Int> = [7]; outputLine(values[9223372036854775807]); }
else if pick == 9 { values: mut List<Int> = []; outputLine(pop_back(mut values)); }
else if pick == 10 { values: mut List<Int> = [7]; outputLine(pop_back(mut values)); pop_back(mut values); }
else if pick == 11 { outputLine("prefix", textAt("x", 1)); }
else if pick == 12 { var n := 0; loop n < 2 { outputLine(textAt("x", n)); n = n + 1; } }
else if pick == 13 { outputLine(textSlice("x", 0, 2), textAt("", 0)); }

