            next = scanned.next;
        } else {
            symbol := readSymbol(source, cursor);
            if symbol == "" {
                lexFail(source, cursor, prefix, "unsupported symbol: " + ch);
            }
            if startsWithAt(source, cursor, "=!") and not startsWithAt(source, cursor, "=!=") {
                lexFail(source, cursor, prefix, "incomplete operator =!; use =!=");
            }
            if startsWithAt(source, cursor, "&&") {
                lexFail(source, cursor, prefix, "unsupported operator &&; use and");
            }
            if startsWithAt(source, cursor, "||") {
                lexFail(source, cursor, prefix, "unsupported operator ||; use or");
            }
            kind = TOKEN_KIND_SYMBOL();
            value = symbol;
            next = cursor + textLength(symbol);
        }
        push_back(mut tokens, (kind = kind, text = value, offset = start, line = startLine, column = startColumn));
        advanced := advanceLines(source, start, next, line, lineStart);
        line = advanced.line;
        lineStart = advanced.lineStart;
        cursor = next;
    }
    tokens
}
/* Lite-written parser core. Starts with the type grammar; declaration/body slices follow. */


/** One flat parse node: kind, name, detail text and source position. */
Node := type (kind: String, name: String, detail: String, offset: Int, line: Int, column: Int);

/** Parse nodes in source order. */
Nodes := type List<Node>;

/* Parse-node kind spellings. Zero-argument accessors because Lite has no enum
   and top-level values cannot be captured by functions yet. */
/** Canonical node kind for one type alias. */
NODE_KIND_TYPE_ALIAS := fn(): String { "TypeAlias" }

/** Canonical node kind for one declaration. */
NODE_KIND_DECLARATION := fn(): String { "Declaration" }

/** Canonical node kind for a complete program. */
NODE_KIND_PROGRAM := fn(): String { "Program" }

/** Reports one token-positioned parser diagnostic and exits 2. */
parseFail := fn(token: Token, prefix: String, message: String): Unit {
    fail(prefix, decimalText(token.line) + ":" + decimalText(token.column) + ": " + message);
}

/** Number of tokens, including the final EOF token. */
tokenCount := fn(tokens: Tokens): Int {
    var count := 0;
    loop tokens as token {
        if token.kind == TOKEN_KIND_EOF() { return count + 1; }
        count = count + 1;
    }
    count
}

/** Returns the token at `index`; the caller keeps `index` inside the counted list. */
tokenAt := fn(tokens: Tokens, index: Int): Token {
    tokens[index]
}

/** True when the token is the exact symbol `text`. */
isSymbol := fn(token: Token, text: String): Bool {
    token.kind == TOKEN_KIND_SYMBOL() and token.text == text
}

/** Consumes the exact symbol or reports a parser diagnostic. */
expectSymbol := fn(tokens: Tokens, index: Int, text: String, prefix: String): Int {
    token := tokenAt(tokens, index);
    if not isSymbol(token, text) {
        parseFail(token, prefix, "expected " + text);
    }
    index + 1
}

/** Consumes a simple-item separator, allowing EOF, a closing scope and a directly closed block token as implicit boundaries. */
consumeStatementEnd := fn(tokens: Tokens, index: Int, prefix: String): Int {
    token := tokenAt(tokens, index);
    if isSymbol(token, ";") { return index + 1; }
    if token.kind == TOKEN_KIND_EOF() or isSymbol(token, "}") or
        (index > 0 and isSymbol(tokenAt(tokens, index - 1), "}")) { return index; }
    expectSymbol(tokens, index, ";", prefix)
}

/** Parses one type: a name, `List<T>` or a flat tuple with optional labels. */
parseType := fn(tokens: Tokens, index: Int, prefix: String): (next: Int, text: String) {
    token := tokenAt(tokens, index);
    if token.kind == TOKEN_KIND_NAME() {
        after := tokenAt(tokens, index + 1);
        if isSymbol(after, "<") {
            if token.text =!= "List" {
                parseFail(token, prefix, "unsupported generic type " + token.text);
            }
            inner := self(tokens, index + 2, prefix);
            closed := expectSymbol(tokens, inner.next, ">", prefix);
            return (next = closed, text = "List<" + inner.text + ">");
        }
        numericKind := numericAliasKind(token.text);
        return (next = index + 1, text = if numericKind == "" { token.text } else { numericKind });
    }
    if isSymbol(token, "(") {
        var cursor := index + 1;
        var text := "(";
        var first := true;
        loop true {
            if isSymbol(tokenAt(tokens, cursor), ")") { break; }
            var label := "";
            if tokenAt(tokens, cursor).kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":") {
                label = tokenAt(tokens, cursor).text + ": ";
                cursor = cursor + 2;
            }
            component := self(tokens, cursor, prefix);
            if not first { text = text + ", "; }
            text = text + label + component.text;
            first = false;
            cursor = component.next;
            if isSymbol(tokenAt(tokens, cursor), ",") {
                cursor = cursor + 1;
            } else {
                break;
            }
        }
        closed := expectSymbol(tokens, cursor, ")", prefix);
        return (next = closed, text = text + ")");
    }
    parseFail(token, prefix, "expected a type");
    (next = index, text = "")
}

/** Quotes one String value as valid normalized expression text. */
quotedText := fn(text: String): String {
    escaped := escapedTokenText(text);
    var result := "";
    var index := 0;
    loop index < textLength(escaped) {
        ch := textAt(escaped, index);
        if ch == "\"" { result = result + "\\\""; } else { result = result + ch; }
        index = index + 1;
    }
    result
}

/** Precedence for one binary word or symbol, or 0 when it is not binary. */
binaryLevel := fn(text: String): Int {
    if text == "or" { 2 }
    else if text == "and" { 3 }
    else if text == "==" or text == "=!=" or text == "<" or text == "<!" or text == "<=" or
        text == "<!=" or text == ">" or text == ">!" or text == ">=" or text == ">!=" { 5 }
    else if text == "+" or text == "-" { 10 }
    else if text == "*" or text == "/" or text == "%" or text == ":/" or text == ":%" { 20 }
    else if text == "**" { 25 }
    else { 0 }
}

/** True when a token is a selected binary operator. */
isBinaryToken := fn(token: Token): Bool {
    if token.kind == TOKEN_KIND_KEYWORD() and (token.text == "and" or token.text == "or") { return true; }
    token.kind == TOKEN_KIND_SYMBOL() and binaryLevel(token.text) > 0
}

/**
 * Parses one expression and returns a fully parenthesized normalized text.
 * `if` value expressions are the next slice; this function reports them
 * explicitly instead of guessing a block boundary.
 */
parseExpression := fn(tokens: Tokens, index: Int, prefix: String, minimum: Int): (next: Int, text: String) {
    token := tokenAt(tokens, index);
    var cursor := index;
    var leftText := "";
    var firstLabel := false;
    if token.kind == TOKEN_KIND_KEYWORD() and (token.text == "and" or token.text == "or") {
        operand := self(tokens, index + 1, prefix, 0);
        return (next = operand.next, text = operand.text);
    } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "not" {
        operand := self(tokens, index + 1, prefix, 5);
        leftText = "(not " + operand.text + ")";
        cursor = operand.next;
    } else if token.kind == TOKEN_KIND_SYMBOL() and (token.text == "-" or token.text == "+") {
        operand := self(tokens, index + 1, prefix, 30);
        leftText = "(" + token.text + operand.text + ")";
        cursor = operand.next;
    } else if token.kind == TOKEN_KIND_INT() or token.kind == TOKEN_KIND_FLOAT() {
        leftText = token.text;
        cursor = index + 1;
    } else if token.kind == TOKEN_KIND_STRING() {
        var value := token.text;
        cursor = index + 1;
        loop tokenAt(tokens, cursor).kind == TOKEN_KIND_STRING() {
            value = value + tokenAt(tokens, cursor).text;
            cursor = cursor + 1;
        }
        leftText = "\"" + quotedText(value) + "\"";
    } else if token.kind == TOKEN_KIND_BOOL() {
        leftText = token.text;
        cursor = index + 1;
    } else if token.kind == TOKEN_KIND_NAME() {
        leftText = token.text;
        cursor = index + 1;
        if isSymbol(tokenAt(tokens, cursor), "(") {
            var argText := "";
            var argCount := 0;
            cursor = cursor + 1;
            loop true {
                if isSymbol(tokenAt(tokens, cursor), ")") { break; }
                if argCount > 0 { argText = argText + ", "; }
                if tokenAt(tokens, cursor).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor).text == "mut" {
                    argText = argText + "mut ";
                    cursor = cursor + 1;
                }
                if tokenAt(tokens, cursor).kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "=") {
                    argText = argText + tokenAt(tokens, cursor).text + " = ";
                    cursor = cursor + 2;
                }
                arg := self(tokens, cursor, prefix, 0);
                argText = argText + arg.text;
                cursor = arg.next;
                argCount = argCount + 1;
                if isSymbol(tokenAt(tokens, cursor), ",") {
                    cursor = cursor + 1;
                } else {
                    break;
                }
            }
            cursor = expectSymbol(tokens, cursor, ")", prefix);
            leftText = leftText + "(" + argText + ")";
        }
    } else if isSymbol(token, "(") {
        cursor = index + 1;
        var firstText := "";
        if tokenAt(tokens, cursor).kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "=") {
            firstText = tokenAt(tokens, cursor).text + " = ";
            firstLabel = true;
            cursor = cursor + 2;
        }
        first := self(tokens, cursor, prefix, 0);
        firstText = firstText + first.text;
        cursor = first.next;
        if firstLabel or isSymbol(tokenAt(tokens, cursor), ",") {
            var tupleText := "(" + firstText;
            if isSymbol(tokenAt(tokens, cursor), ",") { cursor = cursor + 1; }
            loop true {
                if isSymbol(tokenAt(tokens, cursor), ")") { break; }
                tupleText = tupleText + ", ";
                if tokenAt(tokens, cursor).kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "=") {
                    tupleText = tupleText + tokenAt(tokens, cursor).text + " = ";
                    cursor = cursor + 2;
                }
                component := self(tokens, cursor, prefix, 0);
                tupleText = tupleText + component.text;
                cursor = component.next;
                if isSymbol(tokenAt(tokens, cursor), ",") {
                    cursor = cursor + 1;
                } else {
                    break;
                }
            }
            cursor = expectSymbol(tokens, cursor, ")", prefix);
            leftText = tupleText + ")";
        } else {
            cursor = expectSymbol(tokens, cursor, ")", prefix);
            leftText = "(" + firstText + ")";
        }
    } else if isSymbol(token, "[") {
        cursor = index + 1;
        var listText := "[";
        var itemCount := 0;
        loop true {
            if isSymbol(tokenAt(tokens, cursor), "]") { break; }
            if itemCount > 0 { listText = listText + ", "; }
            item := self(tokens, cursor, prefix, 0);
            listText = listText + item.text;
            cursor = item.next;
            itemCount = itemCount + 1;
            if isSymbol(tokenAt(tokens, cursor), ",") {
                cursor = cursor + 1;
            } else {
                break;
            }
        }
        cursor = expectSymbol(tokens, cursor, "]", prefix);
        leftText = listText + "]";
    } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "if" {
        condition := self(tokens, index + 1, prefix, 0);
        opening := expectSymbol(tokens, condition.next, "{", prefix);
        branchValue := self(tokens, opening, prefix, 0);
        closing := expectSymbol(tokens, branchValue.next, "}", prefix);
        var ifText := "if " + condition.text + " { " + branchValue.text + " }";
        cursor = closing;
        loop true {
            if tokenAt(tokens, cursor).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor).text == "else" {
                afterElse := cursor + 1;
                if tokenAt(tokens, afterElse).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, afterElse).text == "if" {
                    elseCondition := self(tokens, afterElse + 1, prefix, 0);
                    elseOpening := expectSymbol(tokens, elseCondition.next, "{", prefix);
                    elseValue := self(tokens, elseOpening, prefix, 0);
                    elseClosing := expectSymbol(tokens, elseValue.next, "}", prefix);
                    ifText = ifText + " else if " + elseCondition.text + " { " + elseValue.text + " }";
                    cursor = elseClosing;
                } else {
                    elseOpening := expectSymbol(tokens, afterElse, "{", prefix);
                    elseValue := self(tokens, elseOpening, prefix, 0);
                    elseClosing := expectSymbol(tokens, elseValue.next, "}", prefix);
                    ifText = ifText + " else { " + elseValue.text + " }";
                    cursor = elseClosing;
                    break;
                }
            } else {
                break;
            }
        }
        leftText = ifText;
    } else {
        parseFail(token, prefix, "expected an expression");
        return (next = index, text = "");
    }
    loop true {
        current := tokenAt(tokens, cursor);
        if isSymbol(current, ".") {
            member := tokenAt(tokens, cursor + 1);
            if member.kind == TOKEN_KIND_NAME() or member.kind == TOKEN_KIND_INT() {
                leftText = leftText + "." + member.text;
                cursor = cursor + 2;
            } else {
                parseFail(member, prefix, "expected a field name after .");
            }
        } else if isSymbol(current, "[") {
            indexExpr := self(tokens, cursor + 1, prefix, 0);
            closed := expectSymbol(tokens, indexExpr.next, "]", prefix);
            leftText = leftText + "[" + indexExpr.text + "]";
            cursor = closed;
        } else {
            break;
        }
    }
    loop true {
        operator := tokenAt(tokens, cursor);
        if not isBinaryToken(operator) { break; }
        level := binaryLevel(operator.text);
        if level < minimum { break; }
        if operator.text == "**" {
            var signIndex := index;
            loop isSymbol(tokenAt(tokens, signIndex), "+") or isSymbol(tokenAt(tokens, signIndex), "-") {
                if isSymbol(tokenAt(tokens, signIndex), "-") {
                    parseFail(operator, prefix, "group a negative power base as (-base) or negate the completed power as -(base ** exponent)");
                }
                signIndex = signIndex + 1;
            }
        }
        rightMinimum := if operator.text == "**" { level } else { level + 1 };
        right := self(tokens, cursor + 1, prefix, rightMinimum);
        leftText = "(" + leftText + " " + operator.text + " " + right.text + ")";
        cursor = right.next;
    }
    (next = cursor, text = leftText)
}

/** Parses one declaration into scalar node fields. */
parseDeclaration := fn(tokens: Tokens, index: Int, prefix: String): (next: Int, name: String, detail: String, offset: Int, line: Int, column: Int) {
    var cursor := index;
    var isVar := false;
    if tokenAt(tokens, cursor).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor).text == "var" {
        isVar = true;
        cursor = cursor + 1;
    }
    token := tokenAt(tokens, cursor);
    if token.kind =!= TOKEN_KIND_NAME() {
        parseFail(token, prefix, "expected a declaration name");
    }
    name := token.text;
    cursor = cursor + 1;
    var detail := "";
    if isSymbol(tokenAt(tokens, cursor), ":=") {
        expression := parseExpression(tokens, cursor + 1, prefix, 0);
        detail = (if isVar { "var " } else { "" }) + ":= " + expression.text;
        cursor = expression.next;
    } else if isSymbol(tokenAt(tokens, cursor), ":") {
        cursor = cursor + 1;
        var mutableType := false;
        if tokenAt(tokens, cursor).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor).text == "mut" {
            mutableType = true;
            cursor = cursor + 1;
        }
        parsedType := parseType(tokens, cursor, prefix);
        detail = (if isVar { "var " } else { "" }) +
            (if mutableType { "mut " } else { "" }) + parsedType.text;
        cursor = parsedType.next;
        if isSymbol(tokenAt(tokens, cursor), "=") {
            if isSymbol(tokenAt(tokens, cursor + 1), "?") {
                detail = detail + " = ?";
                cursor = cursor + 2;
            } else {
                expression := parseExpression(tokens, cursor + 1, prefix, 0);
                detail = detail + " = " + expression.text;
                cursor = expression.next;
            }
        } else if isSymbol(tokenAt(tokens, cursor), "?") {
            detail = detail + " = ?";
            cursor = cursor + 1;
        }
    } else {
        parseFail(tokenAt(tokens, cursor), prefix, "expected := or : after declaration name");
    }
    ended := consumeStatementEnd(tokens, cursor, prefix);
    (next = ended, name = name, detail = detail, offset = token.offset, line = token.line, column = token.column)
}

/** Parses a source made only of declarations, ending at EOF. */
parseDeclarations := fn(tokens: Tokens, prefix: String): Nodes {
    count := tokenCount(tokens);
    nodes: mut List<Node> = [];
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() { break; }
        parsed := parseDeclaration(tokens, cursor, prefix);
        push_back(mut nodes, (kind = NODE_KIND_DECLARATION(), name = parsed.name, detail = parsed.detail,
            offset = parsed.offset, line = parsed.line, column = parsed.column));
        cursor = parsed.next;
    }
    nodes
}

/** Parses one `{ ... }` block or the whole source when `closed` is false into normalized text. */
parseBlock := fn(tokens: Tokens, index: Int, prefix: String, closed: Bool): (next: Int, text: String) {
    var cursor := index;
    if closed {
        cursor = expectSymbol(tokens, cursor, "{", prefix);
    }
    var body := "";
    var itemCount := 0;
    loop true {
        token := tokenAt(tokens, cursor);
        if closed and isSymbol(token, "}") {
            cursor = cursor + 1;
            break;
        }
        if token.kind == TOKEN_KIND_EOF() {
            if closed { parseFail(token, prefix, "expected } before end of source"); }
            break;
        }
        if isSymbol(token, "}") {
            parseFail(token, prefix, "unexpected }");
        }
        if token.kind == TOKEN_KIND_KEYWORD() and
            (token.text == "match" or token.text == "record" or token.text == "import" or
                token.text == "using" or token.text == "then" or token.text == "finally") {
            parseFail(token, prefix, "unsupported feature \"" + token.text + "\"");
        }
        if isSymbol(token, ";") { cursor = cursor + 1; continue; }
        var itemText := "";
        if token.kind == TOKEN_KIND_KEYWORD() and token.text == "if" {
            condition := parseExpression(tokens, cursor + 1, prefix, 0);
            if not isSymbol(tokenAt(tokens, condition.next), "{") {
                parseFail(tokenAt(tokens, condition.next), prefix, "expected { after if condition");
            }
            branch := self(tokens, condition.next, prefix, true);
            var branchText := "if " + condition.text + " " + branch.text;
            cursor = branch.next;
            loop true {
                if tokenAt(tokens, cursor).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor).text == "else" {
                    afterElse := cursor + 1;
                    if tokenAt(tokens, afterElse).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, afterElse).text == "if" {
                        elseCondition := parseExpression(tokens, afterElse + 1, prefix, 0);
                        if not isSymbol(tokenAt(tokens, elseCondition.next), "{") {
                            parseFail(tokenAt(tokens, elseCondition.next), prefix, "expected { after else if condition");
                        }
                        elseBranch := self(tokens, elseCondition.next, prefix, true);
                        branchText = branchText + " else if " + elseCondition.text + " " + elseBranch.text;
                        cursor = elseBranch.next;
                    } else {
                        elseBranch := self(tokens, afterElse, prefix, true);
                        branchText = branchText + " else " + elseBranch.text;
                        cursor = elseBranch.next;
                        break;
                    }
                } else {
                    break;
                }
            }
            cursor = consumeStatementEnd(tokens, cursor, prefix);
            itemText = branchText;
        } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "loop" {
            source := parseExpression(tokens, cursor + 1, prefix, 0);
            if tokenAt(tokens, source.next).kind == TOKEN_KIND_NAME() and tokenAt(tokens, source.next).text == "as" {
                variable := tokenAt(tokens, source.next + 1);
                if variable.kind =!= TOKEN_KIND_NAME() {
                    parseFail(variable, prefix, "expected a loop item name after as");
                }
                bodyBlock := self(tokens, source.next + 2, prefix, true);
                itemText = "loop " + source.text + " as " + variable.text + " " + bodyBlock.text;
                cursor = bodyBlock.next;
            } else {
                if not isSymbol(tokenAt(tokens, source.next), "{") {
                    parseFail(tokenAt(tokens, source.next), prefix, "expected { after loop source");
                }
                bodyBlock := self(tokens, source.next, prefix, true);
                itemText = "loop " + source.text + " " + bodyBlock.text;
                cursor = bodyBlock.next;
            }
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        } else if token.kind == TOKEN_KIND_KEYWORD() and (token.text == "break" or token.text == "continue") {
            itemText = token.text;
            cursor = cursor + 1;
            if isSymbol(tokenAt(tokens, cursor), "@") {
                label := tokenAt(tokens, cursor + 1);
                if label.kind =!= TOKEN_KIND_NAME() { parseFail(label, prefix, "expected a loop label after @"); }
                itemText = itemText + " @" + label.text;
                cursor = cursor + 2;
            }
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "return" {
            afterReturn := cursor + 1;
            if isSymbol(tokenAt(tokens, afterReturn), ";") or isSymbol(tokenAt(tokens, afterReturn), "}") or
                tokenAt(tokens, afterReturn).kind == TOKEN_KIND_EOF() {
                itemText = "return";
                cursor = afterReturn;
            } else {
                value := parseExpression(tokens, afterReturn, prefix, 0);
                itemText = "return " + value.text;
                cursor = value.next;
            }
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        } else if token.kind == TOKEN_KIND_SYMBOL() and token.text == "{" {
            blockText := self(tokens, cursor, prefix, true);
            itemText = blockText.text;
            cursor = consumeStatementEnd(tokens, blockText.next, prefix);
        } else if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "fn" {
            name := token.text;
            var afterName := cursor + 3;
            afterName = expectSymbol(tokens, afterName, "(", prefix);
            var parameters := "";
            var parameterCount := 0;
            loop true {
                if isSymbol(tokenAt(tokens, afterName), ")") { break; }
                parameter := tokenAt(tokens, afterName);
                if parameter.kind =!= TOKEN_KIND_NAME() { parseFail(parameter, prefix, "expected a parameter name"); }
                colon := expectSymbol(tokens, afterName + 1, ":", prefix);
                parameterType := parseType(tokens, colon, prefix);
                if parameterCount > 0 { parameters = parameters + ", "; }
                parameters = parameters + parameter.text + ": " + parameterType.text;
                parameterCount = parameterCount + 1;
                afterName = parameterType.next;
                if isSymbol(tokenAt(tokens, afterName), ",") {
                    afterName = afterName + 1;
                } else {
                    break;
                }
            }
            afterName = expectSymbol(tokens, afterName, ")", prefix);
            resultColon := expectSymbol(tokens, afterName, ":", prefix);
            resultType := parseType(tokens, resultColon, prefix);
            if not isSymbol(tokenAt(tokens, resultType.next), "{") {
                parseFail(tokenAt(tokens, resultType.next), prefix, "expected { after function signature");
            }
            functionBody := self(tokens, resultType.next, prefix, true);
            itemText = name + " := fn(" + parameters + "): " + resultType.text + " " + functionBody.text;
            cursor = functionBody.next;
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        } else if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "type" {
            assigned := expectSymbol(tokens, cursor + 1, ":=", prefix);
            typeWord := tokenAt(tokens, assigned);
            if typeWord.kind =!= TOKEN_KIND_KEYWORD() or typeWord.text =!= "type" {
                parseFail(typeWord, prefix, "expected type after :=");
            }
            aliasType := parseType(tokens, assigned + 1, prefix);
            ended := consumeStatementEnd(tokens, aliasType.next, prefix);
            itemText = token.text + " := type " + aliasType.text;
            cursor = ended;
        } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "var" or
            (token.kind == TOKEN_KIND_NAME() and (isSymbol(tokenAt(tokens, cursor + 1), ":=") or
                isSymbol(tokenAt(tokens, cursor + 1), ":"))) {
            declaration := parseDeclaration(tokens, cursor, prefix);
            itemText = declaration.name + " " + declaration.detail;
            cursor = declaration.next;
        } else if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "=") {
            value := parseExpression(tokens, cursor + 2, prefix, 0);
            itemText = token.text + " = " + value.text;
            cursor = value.next;
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        } else {
            expression := parseExpression(tokens, cursor, prefix, 0);
            itemText = expression.text;
            cursor = expression.next;
            cursor = consumeStatementEnd(tokens, cursor, prefix);
        }
        if itemCount > 0 { body = body + "; "; }
        body = body + itemText;
        itemCount = itemCount + 1;
    }
    (next = cursor, text = if closed { "{ " + body + " }" } else { body })
}

/** Parses a complete source as one Program node containing normalized item text. */
parseProgram := fn(tokens: Tokens, prefix: String): Nodes {
    parsed := parseBlock(tokens, 0, prefix, false);
    nodes: mut List<Node> = [];
    push_back(mut nodes, (kind = NODE_KIND_PROGRAM(), name = "", detail = parsed.text, offset = 0, line = 1, column = 1));
    nodes
}

/** Parses one `Name := type Type;` declaration into scalar node fields. */
parseTypeAlias := fn(tokens: Tokens, index: Int, prefix: String): (next: Int, name: String, detail: String, offset: Int, line: Int, column: Int) {
    token := tokenAt(tokens, index);
    if token.kind =!= TOKEN_KIND_NAME() {
        parseFail(token, prefix, "expected a type alias name");
    }
    assigned := expectSymbol(tokens, index + 1, ":=", prefix);
    typeWord := tokenAt(tokens, assigned);
    if typeWord.kind =!= TOKEN_KIND_KEYWORD() or typeWord.text =!= "type" {
        parseFail(typeWord, prefix, "expected type after :=");
    }
    parsed := parseType(tokens, assigned + 1, prefix);
    ended := consumeStatementEnd(tokens, parsed.next, prefix);
    (next = ended, name = token.text, detail = parsed.text,
        offset = token.offset, line = token.line, column = token.column)
}

/** Parses a source made only of type alias declarations, ending at EOF. */
parseTypeDeclarations := fn(tokens: Tokens, prefix: String): Nodes {
    count := tokenCount(tokens);
    nodes: mut List<Node> = [];
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() { break; }
        parsed := parseTypeAlias(tokens, cursor, prefix);
        push_back(mut nodes, (kind = NODE_KIND_TYPE_ALIAS(), name = parsed.name, detail = parsed.detail,
            offset = parsed.offset, line = parsed.line, column = parsed.column));
        cursor = parsed.next;
    }
    nodes
}

/** Formats one parse node as `kind|name|detail|line:column|offset`. */
dumpNode := fn(node: Node): String {
    node.kind + "|" + node.name + "|" + node.detail + "|" + decimalText(node.line) + ":" +
        decimalText(node.column) + "|" + decimalText(node.offset)
}

/** Reports parsed nodes in source order, one per line. */
dumpNodes := fn(nodes: Nodes): Unit {
    loop nodes as node {
        outputLine(dumpNode(node));
    }
}
/* Lite-written checker foundation. Starts with top-level symbols and duplicates. */

/** One top-level symbol: kind, name, detail text and source position. */
Symbol := type (kind: String, name: String, detail: String, offset: Int, line: Int, column: Int);

/** Top-level symbols in source order. */
Symbols := type List<Symbol>;

/** One local binding: name, reassignment mutability, block depth and origin kind. */
Local := type (name: String, typeText: String, mutable: Bool, writable: Bool, depth: Int, kind: String);

/** Local bindings in declaration order, removed when their block closes. */
Locals := type List<Local>;

/** Canonical symbol kind for a type alias. */
SYMBOL_KIND_TYPE := fn(): String { "type" }

/** Canonical symbol kind for a function. */
SYMBOL_KIND_FUNCTION := fn(): String { "function" }

/** Canonical symbol kind for a value declaration. */
SYMBOL_KIND_VALUE := fn(): String { "value" }

/** True for a built-in type name accepted by the bootstrap subset. */
isBuiltinType := fn(name: String): Bool {
    name == "Int" or name == "Float" or name == "String" or name == "Bool" or name == "Unit" or name == "List" or numericAliasKind(name) =!= ""
}

/** True when a read-only text list contains `target`. */
hasText := fn(values: List<String>, target: String): Bool {
    loop values as value {
        if value == target { return true; }
    }
    false
}

/** Returns the newest local with `name`, or -1. */
findLocal := fn(locals: Locals, name: String): Int {
    var index := 0;
    var found := -1;
    loop locals as local {
        if local.name == name { found = index; }
        index = index + 1;
    }
    found
}

/** Returns the index of a local with `name` directly in `depth`, or -1. */
findLocalAtDepth := fn(locals: Locals, name: String, depth: Int): Int {
    var index := 0;
    loop locals as local {
        if local.name == name and local.depth == depth { return index; }
        index = index + 1;
    }
    -1
}

/** True for the admitted built-in scalar type names. */
isScalarType := fn(typeText: String): Bool {
    typeText == "Int" or typeText == "Float" or typeText == "String" or typeText == "Bool" or typeText == "Unit"
}

/** Returns `List<T>`'s element type, or empty text when the type is not a list. */
listElementType := fn(typeText: String): String {
    size := textLength(typeText);
    if size > 5 and startsWithAt(typeText, 0, "List<") and textAt(typeText, size - 1) == ">" {
        return textSlice(typeText, 5, size - 1);
    }
    ""
}

/** Returns the index of the first top-level symbol named `name`, or -1. */
findSymbol := fn(symbols: Symbols, name: String): Int {
    var index := 0;
    loop symbols as symbol {
        if symbol.name == name { return index; }
        index = index + 1;
    }
    -1
}

/** Parses one function symbol's result type text. */
functionResultType := fn(symbol: Symbol): String {
    tokens := tokenize(symbol.detail, "");
    count := tokenCount(tokens);
    var cursor := 0;
    var depth := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if isSymbol(token, "(") { depth = depth + 1; }
        else if isSymbol(token, ")") {
            depth = depth - 1;
            if depth == 0 {
                cursor = cursor + 1;
                break;
            }
        }
        cursor = cursor + 1;
    }
    if not isSymbol(tokenAt(tokens, cursor), ":") { return ""; }
    parsed := parseType(tokens, cursor + 1, "");
    parsed.text
}

/** Returns one function symbol's parameter types in order. */
functionParamTypes := fn(symbol: Symbol): List<String> {
    tokens := tokenize(symbol.detail, "");
    count := tokenCount(tokens);
    types: mut List<String> = [];
    var cursor := 0;
    loop cursor < count {
        if isSymbol(tokenAt(tokens, cursor), "(") { break; }
        cursor = cursor + 1;
    }
    cursor = cursor + 1;
    loop cursor < count {
        if isSymbol(tokenAt(tokens, cursor), ")") { break; }
        colon := expectSymbol(tokens, cursor + 1, ":", "");
        parameterType := parseType(tokens, colon, "");
        push_back(mut types, parameterType.text);
        cursor = parameterType.next;
        if isSymbol(tokenAt(tokens, cursor), ",") {
            cursor = cursor + 1;
        } else {
            break;
        }
    }
    types
}

/** Finds one binary/prefix operator at the first parenthesis depth of normalized text. */
topLevelOperator := fn(text: String): String {
    tokens := tokenize(text, "");
    count := tokenCount(tokens);
    var cursor := 0;
    var depth := 0;
    var found := "";
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if isSymbol(token, "(") {
            depth = depth + 1;
        } else if isSymbol(token, ")") {
            depth = depth - 1;
        } else if depth == 1 {
            if (token.kind == TOKEN_KIND_KEYWORD() and (token.text == "and" or token.text == "or" or token.text == "not")) or
                (token.kind == TOKEN_KIND_SYMBOL() and (token.text == "+" or token.text == "-" or token.text == "*" or
                    token.text == "/" or token.text == "%" or token.text == ":/" or token.text == ":%" or
                    token.text == "**" or token.text == "==" or token.text == "=!=" or token.text == "<" or
                    token.text == "<!" or token.text == "<=" or token.text == "<!=" or token.text == ">" or
                    token.text == ">!" or token.text == ">=" or token.text == ">!=")) {
                found = token.text;
            }
        }
        cursor = cursor + 1;
    }
    found
}

/** Returns the first literal/name type token inside normalized text, or empty. */
firstOperandType := fn(symbols: Symbols, locals: Locals, text: String): String {
    tokens := tokenize(text, "");
    count := tokenCount(tokens);
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_STRING() { return "String"; }
        if token.kind == TOKEN_KIND_INT() { return "Int"; }
        if token.kind == TOKEN_KIND_FLOAT() { return "Float"; }
        if token.kind == TOKEN_KIND_BOOL() { return "Bool"; }
        if token.kind == TOKEN_KIND_NAME() {
            index := findLocal(locals, token.text);
            if index >= 0 { return locals[index].typeText; }
        }
        cursor = cursor + 1;
    }
    ""
}

/** Resolves a bare type-alias name to its detail text. */
resolveAliasName := fn(symbols: Symbols, typeText: String, depth: Int): String {
    if depth > 16 { return typeText; }
    index := findSymbol(symbols, typeText);
    if index >= 0 and symbols[index].kind == SYMBOL_KIND_TYPE() {
        return resolveAliasName(symbols, symbols[index].detail, depth + 1);
    }
    numericKind := numericAliasKind(typeText);
    if numericKind == "" { typeText } else { numericKind }
}

/** Returns one tuple component type by label or positional index, or empty. */
tupleComponentType := fn(typeText: String, member: String): String {
    tokens := tokenize(typeText, "");
    count := tokenCount(tokens);
    var cursor := 0;
    loop cursor < count {
        if isSymbol(tokenAt(tokens, cursor), "(") { break; }
        cursor = cursor + 1;
    }
    cursor = cursor + 1;
    var index := 0;
    loop cursor < count {
        if isSymbol(tokenAt(tokens, cursor), ")") { break; }
        var label := "";
        if tokenAt(tokens, cursor).kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":") {
            label = tokenAt(tokens, cursor).text;
            cursor = cursor + 2;
        }
        component := parseType(tokens, cursor, "");
        namedMatch := label =!= "" and member == label;
        if namedMatch or member == intText(index) {
            return component.text;
        }
        cursor = component.next;
        index = index + 1;
        if isSymbol(tokenAt(tokens, cursor), ",") { cursor = cursor + 1; } else { break; }
    }
    ""
}

/** True when two type texts are compatible for the checked subset. */
typesCompatible := fn(symbols: Symbols, expected: String, actual: String): Bool {
    if expected == "" or actual == "" { return true; }
    expectedType := resolveAliasName(symbols, expected, 0);
    actualType := resolveAliasName(symbols, actual, 0);
    if isScalarType(expectedType) or isScalarType(actualType) {
        return expectedType == actualType;
    }
    if startsWithAt(expectedType, 0, "List<") and startsWithAt(actualType, 0, "List<") {
        return typesCompatible(symbols, listElementType(expectedType), listElementType(actualType));
    }
    if startsWithAt(expectedType, 0, "(") and startsWithAt(actualType, 0, "(") {
        return expectedType == actualType;
    }
    true
}

/** Infers a simple scalar/tuple/list/call/name type from normalized expression text. */
simpleType := fn(symbols: Symbols, locals: Locals, text: String): String {
    size := textLength(text);
    if size == 0 { return ""; }
    if text == "true" or text == "false" { return "Bool"; }
    if startsWithAt(text, 0, "\"") { return "String"; }
    first := textAt(text, 0);
    if isDigit(first) {
        token := tokenAt(tokenize(text, ""), 0);
        if token.kind == TOKEN_KIND_FLOAT() { return "Float"; }
        return "Int";
    }
    if startsWithAt(text, 0, "(-") or startsWithAt(text, 0, "(+") {
        operand := self(symbols, locals, textSlice(text, 2, size - 1));
        if operand == "Float" { return "Float"; }
        return "Int";
    }
    if startsWithAt(text, 0, "not ") { return "Bool"; }
    if startsWithAt(text, 0, "[") {
        if size == 2 { return ""; }
        tokens := tokenize(text, "");
        count := tokenCount(tokens);
        var cursor := 1;
        var depth := 0;
        var endOffset := 0;
        loop cursor < count {
            token := tokenAt(tokens, cursor);
            if isSymbol(token, "(") or isSymbol(token, "[") or isSymbol(token, "{") {
                depth = depth + 1;
            } else if isSymbol(token, ")") or isSymbol(token, "]") or isSymbol(token, "}") {
                if depth == 0 and isSymbol(token, "]") {
                    endOffset = token.offset;
                    break;
                }
                depth = depth - 1;
            } else if isSymbol(token, ",") and depth == 0 {
                endOffset = token.offset;
                break;
            }
            cursor = cursor + 1;
        }
        if endOffset == 0 { return ""; }
        elementType := simpleType(symbols, locals, textSlice(text, tokenAt(tokens, 1).offset, endOffset));
        if elementType == "" { return ""; }
        return "List<" + elementType + ">";
    }
    if startsWithAt(text, 0, "(") {
        operator := topLevelOperator(text);
        if operator == "and" or operator == "or" or operator == "not" or
            operator == "==" or operator == "=!=" or operator == "<" or operator == "<!" or
            operator == "<=" or operator == "<!=" or operator == ">" or operator == ">!" or
            operator == ">=" or operator == ">!=" {
            return "Bool";
        }
        if operator == "+" {
            if firstOperandType(symbols, locals, text) == "String" { return "String"; }
            return "Int";
        }
        if operator == "**" { return "Float"; }
        if operator == "-" or operator == "*" or operator == "/" or operator == "%" or
            operator == ":/" or operator == ":%" {
            return "Int";
        }
        if indexOfText(text, ",", 0) >= 0 or indexOfText(text, " = ", 0) >= 0 { return ""; }
        if size >= 2 { return simpleType(symbols, locals, textSlice(text, 1, size - 1)); }
        return "";
    }
    if isNameStart(first) {
        var field := -1;
        var fieldCursor := 0;
        loop fieldCursor < size {
            if textAt(text, fieldCursor) == "." { field = fieldCursor; }
            fieldCursor = fieldCursor + 1;
        }
        if field > 0 {
            baseText := textSlice(text, 0, field);
            member := textSlice(text, field + 1, size);
            baseType := simpleType(symbols, locals, baseText);
            resolved := resolveAliasName(symbols, baseType, 0);
            return tupleComponentType(resolved, member);
        }
        indexAt := indexOfText(text, "[", 0);
        if indexAt > 0 and textAt(text, size - 1) == "]" {
            baseText := textSlice(text, 0, indexAt);
            indexText := textSlice(text, indexAt + 1, size - 1);
            baseType := simpleType(symbols, locals, baseText);
            resolved := resolveAliasName(symbols, baseType, 0);
            if startsWithAt(resolved, 0, "List<") { return listElementType(resolved); }
            return tupleComponentType(resolved, indexText);
        }
        index := findLocal(locals, text);
        if index >= 0 { return locals[index].typeText; }
        call := indexOfText(text, "(", 0);
        if call > 0 {
            name := textSlice(text, 0, call);
            functionIndex := findSymbol(symbols, name);
            if functionIndex >= 0 and symbols[functionIndex].kind == SYMBOL_KIND_FUNCTION() {
                return functionResultType(symbols[functionIndex]);
            }
            if name == "inputAll" or name == "textAt" or name == "textSlice" { return "String"; }
            if name == "textLength" { return "Int"; }
            if name == "inputFloat" { return "Float"; }
        }
    }
    ""
}

/** Recognizes the normalized direct/grouped Int literal forms that can enter a scalar Float context without widening an established value. */
exactFloatLiteral := fn(text: String): Bool {
    tokens := tokenize(text, "");
    var first := 0;
    var last := tokenCount(tokens) - 2;
    loop first < last and isSymbol(tokenAt(tokens, first), "(") and isSymbol(tokenAt(tokens, last), ")") {
        var depth := 0;
        var cursor := first;
        loop cursor <= last {
            if isSymbol(tokenAt(tokens, cursor), "(") { depth = depth + 1; }
            else if isSymbol(tokenAt(tokens, cursor), ")") {
                depth = depth - 1;
                if depth == 0 { break; }
            }
            cursor = cursor + 1;
        }
        if cursor =!= last { break; }
        first = first + 1;
        last = last - 1;
    }
    negative := isSymbol(tokenAt(tokens, first), "-");
    if negative { first = first + 1; }
    if first =!= last or tokenAt(tokens, first).kind =!= TOKEN_KIND_INT() { return false; }
    scanned := scanNumericLiteral(tokenAt(tokens, first).text, 0);
    if scanned.outsideInt or (not negative and scanned.magnitude == -9223372036854775808) { return false; }
    value := if negative { scanned.magnitude } else { 0 - scanned.magnitude };
    intExactlyFloat(value)
}

/** Infers a scalar expression with the checkpoint's exact integer-literal Float context; ordinary values and binary results retain their types. */
contextualSimpleType := fn(symbols: Symbols, locals: Locals, text: String, expected: String): String {
    actual := simpleType(symbols, locals, text);
    if actual == "Int" and resolveAliasName(symbols, expected, 0) == "Float" and exactFloatLiteral(text) { return "Float"; }
    actual
}

/** Builds a token-shaped source position for a symbol diagnostic. */
symbolToken := fn(symbol: Symbol): Token {
    (kind = symbol.kind, text = symbol.name, offset = symbol.offset, line = symbol.line, column = symbol.column)
}

/** Reports one token-positioned checker diagnostic and exits 2. */
checkFail := fn(token: Token, prefix: String, message: String): Unit {
    fail(prefix, decimalText(token.line) + ":" + decimalText(token.column) + ": " + message);
}

/** Skips one balanced `{ ... }` sequence and returns the position after it. */
skipBraces := fn(tokens: Tokens, index: Int, prefix: String): Int {
    var cursor := expectSymbol(tokens, index, "{", prefix);
    var depth := 1;
    loop true {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() {
            checkFail(token, prefix, "unterminated block");
        }
        if isSymbol(token, "{") {
            depth = depth + 1;
        } else if isSymbol(token, "}") {
            depth = depth - 1;
            if depth == 0 { return cursor + 1; }
        }
        cursor = cursor + 1;
    }
    cursor
}

/** Retains sequential value bindings in source order; other duplicate symbol kinds remain unsupported. */
addSymbol := fn(symbols: Symbols, symbol: Symbol, prefix: String): Symbols {
    previous := findSymbol(symbols, symbol.name);
    if previous >= 0 and (symbol.kind =!= SYMBOL_KIND_VALUE() or symbols[previous].kind =!= SYMBOL_KIND_VALUE()) {
        checkFail((kind = symbol.kind, text = symbol.name, offset = symbol.offset,
            line = symbol.line, column = symbol.column), prefix, "duplicate top-level name " + symbol.name);
    }
    result: mut List<Symbol> = [];
    loop symbols as item { push_back(mut result, item); }
    push_back(mut result, symbol);
    result
}

/** Parses one function signature and skips its body into scalar symbol fields. */
parseFunctionSymbol := fn(tokens: Tokens, index: Int, prefix: String): (next: Int, name: String, detail: String, offset: Int, line: Int, column: Int) {
    nameToken := tokenAt(tokens, index);
    afterName := expectSymbol(tokens, index + 1, ":=", prefix);
    functionWord := tokenAt(tokens, afterName);
    if functionWord.kind =!= TOKEN_KIND_KEYWORD() or functionWord.text =!= "fn" {
        checkFail(functionWord, prefix, "expected fn after :=");
    }
    var cursor := expectSymbol(tokens, afterName + 1, "(", prefix);
    var detail := "(";
    var parameterCount := 0;
    parameterNames: mut List<String> = [];
    loop true {
        if isSymbol(tokenAt(tokens, cursor), ")") { break; }
        parameter := tokenAt(tokens, cursor);
        if parameter.kind =!= TOKEN_KIND_NAME() {
            checkFail(parameter, prefix, "expected a parameter name");
        }
        if hasText(parameterNames, parameter.text) {
            checkFail(parameter, prefix, "duplicate parameter " + parameter.text);
        }
        push_back(mut parameterNames, parameter.text);
        colon := expectSymbol(tokens, cursor + 1, ":", prefix);
        parameterType := parseType(tokens, colon, prefix);
        if parameterCount > 0 { detail = detail + ", "; }
        detail = detail + parameter.text + ": " + parameterType.text;
        parameterCount = parameterCount + 1;
        cursor = parameterType.next;
        if isSymbol(tokenAt(tokens, cursor), ",") {
            cursor = cursor + 1;
        } else {
            break;
        }
    }
    cursor = expectSymbol(tokens, cursor, ")", prefix);
    resultColon := expectSymbol(tokens, cursor, ":", prefix);
    resultType := parseType(tokens, resultColon, prefix);
    detail = detail + "): " + resultType.text;
    var afterBody := skipBraces(tokens, resultType.next, prefix);
    if isSymbol(tokenAt(tokens, afterBody), ";") { afterBody = afterBody + 1; }
    (next = afterBody, name = nameToken.text, detail = detail,
        offset = nameToken.offset, line = nameToken.line, column = nameToken.column)
}

/** Collects top-level symbols, retaining each sequential value declaration. */
collectSymbols := fn(tokens: Tokens, prefix: String): Symbols {
    count := tokenCount(tokens);
    var symbols: mut List<Symbol> = [];
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if isSymbol(token, ";") { cursor = cursor + 1; continue; }
        if token.kind == TOKEN_KIND_EOF() { break; }
        if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "type" {
            afterName := expectSymbol(tokens, cursor + 1, ":=", prefix);
            parsedType := parseType(tokens, afterName + 1, prefix);
            ended := expectSymbol(tokens, parsedType.next, ";", prefix);
            symbols = addSymbol(symbols, (kind = SYMBOL_KIND_TYPE(), name = token.text, detail = parsedType.text,
                offset = token.offset, line = token.line, column = token.column), prefix);
            cursor = ended;
        } else if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "fn" {
            parsed := parseFunctionSymbol(tokens, cursor, prefix);
            symbols = addSymbol(symbols, (kind = SYMBOL_KIND_FUNCTION(), name = parsed.name, detail = parsed.detail,
                offset = parsed.offset, line = parsed.line, column = parsed.column), prefix);
            cursor = parsed.next;
        } else if (token.kind == TOKEN_KIND_KEYWORD() and token.text == "var") or
            (token.kind == TOKEN_KIND_NAME() and (isSymbol(tokenAt(tokens, cursor + 1), ":=") or
                isSymbol(tokenAt(tokens, cursor + 1), ":"))) {
            declaration := parseDeclaration(tokens, cursor, prefix);
            nameToken := tokenAt(tokens, cursor + (if token.kind == TOKEN_KIND_KEYWORD() { 1 } else { 0 }));
            symbols = addSymbol(symbols, (kind = SYMBOL_KIND_VALUE(), name = declaration.name, detail = declaration.detail,
                offset = nameToken.offset, line = nameToken.line, column = nameToken.column), prefix);
            cursor = declaration.next;
        } else if token.kind == TOKEN_KIND_KEYWORD() and token.text == "loop" {
            var body := cursor + 1;
            if not isSymbol(tokenAt(tokens, body), "{") {
                sequence := parseExpression(tokens, body, prefix, 0);
                body = sequence.next;
                if tokenAt(tokens, body).kind == TOKEN_KIND_NAME() and tokenAt(tokens, body).text == "as" {
                    receiver := tokenAt(tokens, body + 1);
                    if receiver.kind =!= TOKEN_KIND_NAME() { checkFail(receiver, prefix, "expected a loop item name after as"); }
                    body = body + 2;
                }
            }
            cursor = skipBraces(tokens, body, prefix);
            if isSymbol(tokenAt(tokens, cursor), ";") { cursor = cursor + 1; }
        } else if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "=") {
            value := parseExpression(tokens, cursor + 2, prefix, 0);
            cursor = consumeStatementEnd(tokens, value.next, prefix);
        } else {
            expression := parseExpression(tokens, cursor, prefix, 0);
            cursor = expression.next;
            if isSymbol(tokenAt(tokens, cursor), ";") { cursor = cursor + 1; }
        }
    }
    symbols
}

/** True for the four builtin list end operations. */
isListEndOperation := fn(name: String): Bool {
    name == "push_back" or name == "push_front" or name == "pop_back" or name == "pop_front"
}

/** Checks block-local declarations, parameter scopes and statement assignments. */
checkLocals := fn(tokens: Tokens, prefix: String, symbols: Symbols): Unit {
    count := tokenCount(tokens);
    locals: mut List<Local> = [];
    var localCount := 0;
    var depth := 0;
    var parens := 0;
    var brackets := 0;
    var cursor := 0;
    var functionResult := "";
    var functionBodyDepth := -1;
    var pendingLoop := false;
    var loopDepth := 0;
    loopBodies: mut List<Int> = [];
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() { break; }
        if isSymbol(token, "{") {
            if pendingLoop {
                push_back(mut loopBodies, depth + 1);
                loopDepth = loopDepth + 1;
                pendingLoop = false;
            }
            depth = depth + 1;
            cursor = cursor + 1;
            continue;
        }
        if isSymbol(token, "}") {
            if loopDepth > 0 and loopBodies[loopDepth - 1] == depth {
                pop_back(mut loopBodies);
                loopDepth = loopDepth - 1;
            }
            loop localCount > 0 and locals[localCount - 1].depth >= depth {
                pop_back(mut locals);
                localCount = localCount - 1;
            }
            if functionBodyDepth == depth {
                functionResult = "";
                functionBodyDepth = -1;
            }
            depth = depth - 1;
            cursor = cursor + 1;
            continue;
        }
        if isSymbol(token, "(") { parens = parens + 1; cursor = cursor + 1; continue; }
        if isSymbol(token, ")") { parens = parens - 1; cursor = cursor + 1; continue; }
        if isSymbol(token, "[") { brackets = brackets + 1; cursor = cursor + 1; continue; }
        if isSymbol(token, "]") { brackets = brackets - 1; cursor = cursor + 1; continue; }
        if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "type" {
            afterName := expectSymbol(tokens, cursor + 1, ":=", prefix);
            aliasType := parseType(tokens, afterName + 1, prefix);
            cursor = expectSymbol(tokens, aliasType.next, ";", prefix);
            continue;
        }
        if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), ":=") and
            tokenAt(tokens, cursor + 2).kind == TOKEN_KIND_KEYWORD() and tokenAt(tokens, cursor + 2).text == "fn" {
            var parameterCursor := expectSymbol(tokens, cursor + 3, "(", prefix);
            loop true {
                if isSymbol(tokenAt(tokens, parameterCursor), ")") { break; }
                parameter := tokenAt(tokens, parameterCursor);
                if parameter.kind =!= TOKEN_KIND_NAME() {
                    checkFail(parameter, prefix, "expected a parameter name");
                }
                if findLocalAtDepth(locals, parameter.text, depth + 1) >= 0 {
                    checkFail(parameter, prefix, "duplicate parameter " + parameter.text);
                }
                colon := expectSymbol(tokens, parameterCursor + 1, ":", prefix);
                parameterType := parseType(tokens, colon, prefix);
                push_back(mut locals, (name = parameter.text, typeText = parameterType.text,
                    mutable = false, writable = false, depth = depth + 1, kind = "parameter"));
                localCount = localCount + 1;
                parameterCursor = parameterType.next;
                if isSymbol(tokenAt(tokens, parameterCursor), ",") {
                    parameterCursor = parameterCursor + 1;
                } else {
                    break;
                }
            }
            parameterCursor = expectSymbol(tokens, parameterCursor, ")", prefix);
            resultColon := expectSymbol(tokens, parameterCursor, ":", prefix);
            resultType := parseType(tokens, resultColon, prefix);
            functionResult = resultType.text;
            functionBodyDepth = depth + 1;
            cursor = resultType.next;
            continue;
        }
        if token.kind == TOKEN_KIND_KEYWORD() and token.text == "return" {
            if functionBodyDepth < 0 {
                checkFail(token, prefix, "return outside function");
            }
            afterReturn := cursor + 1;
            if isSymbol(tokenAt(tokens, afterReturn), ";") or isSymbol(tokenAt(tokens, afterReturn), "}") or
                tokenAt(tokens, afterReturn).kind == TOKEN_KIND_EOF() {
                if functionResult =!= "" and functionResult =!= "Unit" {
                    checkFail(token, prefix, "return requires a value");
                }
                cursor = afterReturn;
            } else {
                value := parseExpression(tokens, afterReturn, prefix, 0);
                inferred := contextualSimpleType(symbols, locals, value.text, functionResult);
                if not typesCompatible(symbols, functionResult, inferred) {
                    checkFail(token, prefix, "cannot return " + inferred + " from function returning " + functionResult);
                }
                cursor = value.next;
            }
            if isSymbol(tokenAt(tokens, cursor), ";") { cursor = cursor + 1; }
            continue;
        }
        if token.kind == TOKEN_KIND_KEYWORD() and (token.text == "break" or token.text == "continue") {
            if loopDepth == 0 {
                checkFail(token, prefix, token.text + " outside loop");
            }
            cursor = cursor + 1;
            if isSymbol(tokenAt(tokens, cursor), "@") { cursor = cursor + 2; }
            if isSymbol(tokenAt(tokens, cursor), ";") { cursor = cursor + 1; }
            continue;
        }
        if token.kind == TOKEN_KIND_KEYWORD() and token.text == "if" {
            condition := parseExpression(tokens, cursor + 1, prefix, 0);
            conditionType := simpleType(symbols, locals, condition.text);
            if isScalarType(conditionType) and conditionType =!= "Bool" {
                checkFail(token, prefix, "if condition must be Bool");
            }
            cursor = condition.next;
            continue;
        }
        if token.kind == TOKEN_KIND_KEYWORD() and token.text == "loop" {
            if isSymbol(tokenAt(tokens, cursor + 1), "{") {
                pendingLoop = true;
                cursor = cursor + 1;
                continue;
            }
            source := parseExpression(tokens, cursor + 1, prefix, 0);
            if tokenAt(tokens, source.next).kind == TOKEN_KIND_NAME() and tokenAt(tokens, source.next).text == "as" {
                itemToken := tokenAt(tokens, source.next + 1);
                if itemToken.kind =!= TOKEN_KIND_NAME() {
                    checkFail(itemToken, prefix, "expected a loop item name after as");
                }
                sourceType := simpleType(symbols, locals, source.text);
                itemType := listElementType(sourceType);
                push_back(mut locals, (name = itemToken.text, typeText = itemType, mutable = false,
                    writable = false, depth = depth + 1, kind = "loop item"));
                localCount = localCount + 1;
                cursor = source.next + 2;
                pendingLoop = true;
            } else {
                conditionType := simpleType(symbols, locals, source.text);
                if isScalarType(conditionType) and conditionType =!= "Bool" {
                    checkFail(token, prefix, "loop condition must be Bool");
                }
                cursor = source.next;
                pendingLoop = true;
            }
            continue;
        }
        if token.kind == TOKEN_KIND_NAME() and isListEndOperation(token.text) and
            isSymbol(tokenAt(tokens, cursor + 1), "(") {
            firstArgument := tokenAt(tokens, cursor + 2);
            if firstArgument.kind =!= TOKEN_KIND_KEYWORD() or firstArgument.text =!= "mut" {
                checkFail(token, prefix, token.text + " requires mut list argument");
            }
            listToken := tokenAt(tokens, cursor + 3);
            if listToken.kind =!= TOKEN_KIND_NAME() {
                checkFail(listToken, prefix, "expected a list name after mut");
            }
            index := findLocal(locals, listToken.text);
            if index < 0 {
                checkFail(listToken, prefix, "unknown local " + listToken.text);
            }
            if not locals[index].writable {
                checkFail(listToken, prefix, "cannot mutate list " + listToken.text + " without mut");
            }
            cursor = cursor + 4;
            continue;
        }
        if (token.kind == TOKEN_KIND_KEYWORD() and token.text == "var") or
            (token.kind == TOKEN_KIND_NAME() and (isSymbol(tokenAt(tokens, cursor + 1), ":=") or
                isSymbol(tokenAt(tokens, cursor + 1), ":"))) {
            declaration := parseDeclaration(tokens, cursor, prefix);
            nameToken := tokenAt(tokens, cursor + (if token.kind == TOKEN_KIND_KEYWORD() { 1 } else { 0 }));
            mutable := startsWithAt(declaration.detail, 0, "var ");
            var writable := false;
            var work := declaration.detail;
            if mutable { work = textSlice(work, 4, textLength(work)); }
            var typeText := "";
            var initText := "";
            if startsWithAt(work, 0, ":= ") {
                initText = textSlice(work, 3, textLength(work));
                typeText = simpleType(symbols, locals, initText);
            } else {
                if startsWithAt(work, 0, "mut ") {
                    writable = true;
                    work = textSlice(work, 4, textLength(work));
                }
                split := indexOfText(work, " = ", 0);
                if split >= 0 {
                    typeText = textSlice(work, 0, split);
                    initText = textSlice(work, split + 3, textLength(work));
                } else {
                    typeText = work;
                }
                if initText =!= "" and initText =!= "?" {
                    inferred := contextualSimpleType(symbols, locals, initText, typeText);
                    if not typesCompatible(symbols, typeText, inferred) {
                        checkFail(nameToken, prefix, "cannot initialize " + typeText + " with " + inferred);
                    }
                }
            }
            push_back(mut locals, (name = declaration.name, typeText = typeText, mutable = mutable,
                writable = writable, depth = depth, kind = "local"));
            localCount = localCount + 1;
            cursor = declaration.next;
            continue;
        }
        if parens == 0 and brackets == 0 and token.kind == TOKEN_KIND_NAME() and
            isSymbol(tokenAt(tokens, cursor + 1), "=") {
            previous := tokenAt(tokens, cursor - 1);
            if isSymbol(previous, "(") or isSymbol(previous, ",") {
                cursor = cursor + 1;
                continue;
            }
            index := findLocal(locals, token.text);
            if index < 0 {
                checkFail(token, prefix, "unknown local " + token.text);
            }
            if not locals[index].mutable {
                checkFail(token, prefix, "cannot assign to immutable local " + token.text);
            }
            value := parseExpression(tokens, cursor + 2, prefix, 0);
            localType := locals[index].typeText;
            inferred := contextualSimpleType(symbols, locals, value.text, localType);
            if not typesCompatible(symbols, localType, inferred) {
                checkFail(token, prefix, "cannot assign " + inferred + " to " + localType + " local " + token.text);
            }
            cursor = value.next;
            if isSymbol(tokenAt(tokens, cursor), ";") { cursor = cursor + 1; }
            continue;
        }
        cursor = cursor + 1;
    }
}

/** Validates every type name inside one type or signature text. */
validateTypeText := fn(symbols: Symbols, text: String, depth: Int, symbol: Symbol, prefix: String): Unit {
    if depth > 16 {
        checkFail(symbolToken(symbol), prefix, "recursive type alias " + symbol.name);
    }
    tokens := tokenize(text, "");
    count := tokenCount(tokens);
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() { break; }
        if token.kind == TOKEN_KIND_NAME() {
            next := tokenAt(tokens, cursor + 1);
            if isSymbol(next, ":") {
                cursor = cursor + 1;
            } else if not isBuiltinType(token.text) {
                index := findSymbol(symbols, token.text);
                if index < 0 {
                    checkFail(symbolToken(symbol), prefix, "unknown type " + token.text);
                }
                alias := symbols[index];
                if alias.kind =!= SYMBOL_KIND_TYPE() {
                    checkFail(symbolToken(symbol), prefix, "name " + token.text + " is not a type");
                }
                validateTypeText(symbols, alias.detail, depth + 1, alias, prefix);
            }
        }
        cursor = cursor + 1;
    }
}

/** Validates the annotation of one value declaration, if it has one. */
validateValueSymbol := fn(symbols: Symbols, symbol: Symbol, prefix: String): Unit {
    var text := symbol.detail;
    if startsWithAt(text, 0, "var ") { text = textSlice(text, 4, textLength(text)); }
    if startsWithAt(text, 0, "mut ") { text = textSlice(text, 4, textLength(text)); }
    if startsWithAt(text, 0, ":= ") { return; }
    split := indexOfText(text, " = ", 0);
    if split >= 0 { text = textSlice(text, 0, split); }
    if text == "" { return; }
    validateTypeText(symbols, text, 0, symbol, prefix);
}

/** Validates collected symbols' type annotations and signatures. */
validateSymbols := fn(symbols: Symbols, prefix: String): Unit {
    loop symbols as symbol {
        if symbol.kind == SYMBOL_KIND_TYPE() or symbol.kind == SYMBOL_KIND_FUNCTION() {
            validateTypeText(symbols, symbol.detail, 0, symbol, prefix);
        } else {
            validateValueSymbol(symbols, symbol, prefix);
        }
    }
}

/** Number of parameters in one function symbol's detail text. */
functionArity := fn(symbol: Symbol): Int {
    tokens := tokenize(symbol.detail, "");
    count := tokenCount(tokens);
    var cursor := 0;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if isSymbol(token, "(") { break; }
        cursor = cursor + 1;
    }
    cursor = cursor + 1;
    if isSymbol(tokenAt(tokens, cursor), ")") { return 0; }
    var depth := 0;
    var arguments := 1;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if isSymbol(token, "(") or isSymbol(token, "[") or isSymbol(token, "{") {
            depth = depth + 1;
        } else if isSymbol(token, ")") or isSymbol(token, "]") or isSymbol(token, "}") {
            if depth == 0 and isSymbol(token, ")") { return arguments; }
            depth = depth - 1;
        } else if isSymbol(token, ",") and depth == 0 {
            arguments = arguments + 1;
        }
        cursor = cursor + 1;
    }
    arguments
}

/** Counts one call's top-level arguments starting at its opening parenthesis. */
callArity := fn(tokens: Tokens, openIndex: Int, prefix: String): Int {
    count := tokenCount(tokens);
    var cursor := openIndex + 1;
    if isSymbol(tokenAt(tokens, cursor), ")") { return 0; }
    var depth := 0;
    var arguments := 1;
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() {
            checkFail(token, prefix, "unterminated call");
        }
        if isSymbol(token, "(") or isSymbol(token, "[") or isSymbol(token, "{") {
            depth = depth + 1;
        } else if isSymbol(token, ")") or isSymbol(token, "]") or isSymbol(token, "}") {
            if depth == 0 and isSymbol(token, ")") { return arguments; }
            depth = depth - 1;
        } else if isSymbol(token, ",") and depth == 0 {
            arguments = arguments + 1;
        }
        cursor = cursor + 1;
    }
    arguments
}

/** Checks direct calls to known top-level functions for matching arity. */
checkCalls := fn(tokens: Tokens, symbols: Symbols, prefix: String): Unit {
    count := tokenCount(tokens);
    var cursor := 0;
    emptyLocals: List<Local> = [];
    loop cursor < count {
        token := tokenAt(tokens, cursor);
        if token.kind == TOKEN_KIND_EOF() { break; }
        if token.kind == TOKEN_KIND_NAME() and isSymbol(tokenAt(tokens, cursor + 1), "(") {
            index := findSymbol(symbols, token.text);
            if index >= 0 and symbols[index].kind == SYMBOL_KIND_FUNCTION() {
                expected := functionArity(symbols[index]);
                actual := callArity(tokens, cursor + 1, prefix);
                if expected =!= actual {
                    checkFail(token, prefix, "function " + token.text + " expects " + decimalText(expected) +
                        " arguments, got " + decimalText(actual));
                }
                parameterTypes := functionParamTypes(symbols[index]);
                var argumentCursor := cursor + 2;
                var argumentIndex := 0;
                loop argumentIndex < expected {
                    if tokenAt(tokens, argumentCursor).kind == TOKEN_KIND_KEYWORD() and
                        tokenAt(tokens, argumentCursor).text == "mut" {
                        argumentCursor = argumentCursor + 1;
                    }
                    if tokenAt(tokens, argumentCursor).kind == TOKEN_KIND_NAME() and
                        isSymbol(tokenAt(tokens, argumentCursor + 1), "=") {
                        argumentCursor = argumentCursor + 2;
                    }
                    argument := parseExpression(tokens, argumentCursor, prefix, 0);
                    expectedType := parameterTypes[argumentIndex];
                    inferred := contextualSimpleType(symbols, emptyLocals, argument.text, expectedType);
                    if not typesCompatible(symbols, expectedType, inferred) {
                        checkFail(token, prefix, "argument " + decimalText(argumentIndex + 1) + " of " + token.text +
                            " expects " + expectedType + ", got " + inferred);
                    }
                    argumentCursor = argument.next;
                    argumentIndex = argumentIndex + 1;
                    if argumentIndex < expected and isSymbol(tokenAt(tokens, argumentCursor), ",") {
                        argumentCursor = argumentCursor + 1;
                    }
                }
            }
        }
        cursor = cursor + 1;
    }
}

/** Collects, validates and checks one source. */
checkSource := fn(tokens: Tokens, prefix: String): Symbols {
    symbols := collectSymbols(tokens, prefix);
    validateSymbols(symbols, prefix);
    checkLocals(tokens, prefix, symbols);
    checkCalls(tokens, symbols, prefix);
    symbols
}

/** Formats one symbol as `kind|name|detail|line:column|offset`. */
dumpSymbol := fn(symbol: Symbol): String {
    symbol.kind + "|" + symbol.name + "|" + symbol.detail + "|" + decimalText(symbol.line) + ":" +
        decimalText(symbol.column) + "|" + decimalText(symbol.offset)
}

/** Reports collected symbols in source order, one per line. */
dumpSymbols := fn(symbols: Symbols): Unit {
    loop symbols as symbol {
        outputLine(dumpSymbol(symbol));
    }
}

var prefix := "";
var argCount := 0;
loop inputArgs() as argument {
    if argCount == 0 { prefix = argument; }
    argCount = argCount + 1;
}
if argCount > 1 {
    reportError("expected at most one logical source name argument");
    exit(2);
}
tokens := tokenize(inputAll(), prefix);
dumpSymbols(checkSource(tokens, prefix));

